macro_rules! inflateGetHeader {
    () => {
        # [doc = " Requests that gzip header information be stored in the provided [`gz_header`] structure."] # [doc = ""] # [doc = " The [`inflateGetHeader`] function may be called after [`inflateInit2_`] or [`inflateReset`], and before the first call of [`inflate`]."] # [doc = " As [`inflate`] processes the gzip stream, `head.done` is zero until the header is completed, at which time `head.done` is set to one."] # [doc = " If a zlib stream is being decoded, then `head.done` is set to `-1` to indicate that there will be no gzip header information forthcoming."] # [doc = " Note that [`Z_BLOCK`] can be used to force [`inflate`] to return immediately after header processing is complete and before any actual data is decompressed."] # [doc = ""] # [doc = " - The `text`, `time`, `xflags`, and `os` fields are filled in with the gzip header contents."] # [doc = " - `hcrc` is set to true if there is a header CRC. (The header CRC was valid if done is set to one.)"] # [doc = " - If `extra` is not `NULL`, then `extra_max` contains the maximum number of bytes to write to extra."] # [doc = "   Once `done` is `true`, `extra_len` contains the actual extra field length,"] # [doc = "   and `extra` contains the extra field, or that field truncated if `extra_max` is less than `extra_len`."] # [doc = " - If `name` is not `NULL`, then up to `name_max` characters are written there, terminated with a zero unless the length is greater than `name_max`."] # [doc = " - If `comment` is not `NULL`, then up to `comm_max` characters are written there, terminated with a zero unless the length is greater than `comm_max`."] # [doc = ""] # [doc = " When any of `extra`, `name`, or `comment` are not `NULL` and the respective field is not present in the header, then that field is set to `NULL` to signal its absence."] # [doc = " This allows the use of [`deflateSetHeader`] with the returned structure to duplicate the header. However if those fields are set to allocated memory,"] # [doc = " then the application will need to save those pointers elsewhere so that they can be eventually freed."] # [doc = ""] # [doc = " If [`inflateGetHeader`] is not used, then the header information is simply discarded. The header is always checked for validity, including the header CRC if present."] # [doc = " [`inflateReset`] will reset the process to discard the header information."] # [doc = " The application would need to call [`inflateGetHeader`] again to retrieve the header from the next gzip stream."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_STREAM_ERROR`] if the source stream state was inconsistent (such as zalloc being NULL)"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `strm` is `NULL`"] # [doc = "     - `strm` satisfies the requirements of `&mut *strm` and was initialized with [`inflateInit_`] or similar"] # [doc = " * Either"] # [doc = "     - `head` is `NULL`"] # [doc = "     - `head` satisfies the requirements of `&mut *head`"] # [doc = " * If `head` is not `NULL`:"] # [doc = "     - if `head.extra` is not NULL, it must be writable for at least `head.extra_max` bytes"] # [doc = "     - if `head.name` is not NULL, it must be writable for at least `head.name_max` bytes"] # [doc = "     - if `head.comment` is not NULL, it must be writable for at least `head.comm_max` bytes"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (inflateGetHeader))] pub unsafe extern "C-unwind" fn inflateGetHeader (strm : z_streamp , head : gz_headerp) -> c_int { let Some (stream) = (unsafe { InflateStream :: from_stream_mut (strm) }) else { return ReturnCode :: StreamError as _ ; } ; let header = unsafe { head . as_mut () } ; zlib_rs :: inflate :: get_header (stream , header) as i32 }
    };
}

inflateGetHeader!()